css.rules:
display: flex;
flex-direction: column;
gap: var(--gap);

display: grid;
grid-template-columns: min(40em, 100%);
justify-content: center;
gap: var(--gap);

display: flex;
flex-direction: column;
align-items: center;
gap: var(--gap);

display: grid;
grid-template-rows: auto minmax(0, 1fr) auto;
height: 100dvh;

display: flex;
flex-direction: column;
height: 100dvh;
/* the middle child */ flex: 1;
min-height: 0;
overflow: auto;

/* the page */ display: block;

/* each band */
width: 100%;
background: var(--band-bg);
padding-block: clamp(3em, 8vh, 7em);

/* the track inside it */
max-width: 70em;
margin-inline: auto;

/* the page */
height: 100dvh;
overflow-y: auto;
scroll-snap-type: y proximity;

/* each band */
min-height: 100dvh;
scroll-snap-align: start;

display: grid;
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* each child */
flex: 1 1 20em;
min-width: 0;

/* each child */
float: left;
width: 50%;

/* the row */
overflow: hidden;

display: grid;
grid-template-columns: 16em minmax(0, 1fr);
gap: var(--gap);

display: grid;
grid-template-columns: minmax(0, 1fr) minmax(0, min(32%, 26rem));
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* the rail */
flex: 0 1 16em;

/* the body */
flex: 1 1 24em;
min-width: 0;

display: grid;
grid-template-columns: repeat(3, minmax(0, 1fr));
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* each child */
flex: 1 1 16em;
min-width: 0;

/* the row, as above, plus on each child */
background: var(--surface);
border: 1px solid var(--line);
border-radius: var(--radius);
padding: var(--pad);

display: grid;
grid-template-columns: 16em minmax(0, 1fr) 18em;
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* the rails */
flex: 0 1 16em;

/* the middle */
flex: 1 1 28em;
min-width: 0;

/* on the row */
height: 100dvh;

/* on each column */
overflow-y: auto;
min-height: 0;

display: grid;
grid-template-columns: minmax(0, 1fr) 15em 12em;
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* main */ flex: 1 1 28em; min-width: 0;
/* aside */ flex: 0 1 15em;
/* aside */ flex: 0 1 12em;

display: grid;
grid-template-columns: repeat(4, minmax(0, 1fr));
grid-auto-rows: 12em;
gap: var(--gap);

/* the big one */
grid-column: span 2;
grid-row: span 2;

grid-template-columns: repeat(auto-fit, minmax(min(16em, 100%), 1fr));

/* every span, below the fold width */
@media (width < 40em) { grid-column: auto; grid-row: auto; }

display: grid;
grid-template-columns: repeat(auto-fill, minmax(min(14em, 100%), 1fr));
gap: var(--gap);

display: flex;
flex-wrap: wrap;
gap: var(--gap);

/* each child */
flex: 1 1 14em;
min-width: 0;

columns: 14em;
gap: var(--gap);

/* each child */
break-inside: avoid;

column-rule: 1px solid var(--line);

/* on a child that must not be split */
break-inside: avoid;
